CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), number bigint GENERATED ALWAYS AS IDENTITY UNIQUE, subject text NOT NULL, description text, created_by uuid NOT NULL, organization_id uuid, department_id uuid, ticket_type_id uuid, ticket_kind_id uuid, priority integer NOT NULL DEFAULT 3 CHECK (priority BETWEEN 1 AND 5), status text NOT NULL DEFAULT 'new', assignee_id uuid, development_required boolean NOT NULL DEFAULT false, development_board_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz);
CREATE TABLE IF NOT EXISTS ticket_observers (ticket_id uuid NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (ticket_id, user_id));
CREATE TABLE IF NOT EXISTS ticket_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, author_id uuid NOT NULL, body text NOT NULL, is_internal boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ticket_sla_instances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, policy_id text NOT NULL, target_at timestamptz, breached_at timestamptz, status text NOT NULL DEFAULT 'running');
CREATE TABLE IF NOT EXISTS outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL UNIQUE, event_type text NOT NULL, event_version integer NOT NULL DEFAULT 1, aggregate_type text NOT NULL, aggregate_id text NOT NULL, correlation_id text NOT NULL, payload jsonb NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, attempts integer NOT NULL DEFAULT 0, last_error text);
CREATE INDEX IF NOT EXISTS service_desk_outbox_pending_idx ON outbox_events (occurred_at) WHERE published_at IS NULL;
